+static void nap_add(u64* counter, u64 value) {
+  if (~(u64)0 - *counter < value) nap_overflow = true;
+  else *counter += value;
+}
+#define NAP_CLASS(c, field, n) do { if (nap_enabled) \
+  nap_add(&nap_classes[nap_phase][c].field, (n)); } while (0)
+#define NAP_TAG(c, t, field, n) do { if (nap_enabled) \
+  nap_add(&nap_tags[nap_phase][t][c].field, (n)); } while (0)
