+  if (!nap_enabled) return;
+  bool valid = !nap_overflow && pool_size == 1;
+  fputs("NATIVE_ALLOCATIONS {\"version\":1,\"classes\":[", stderr);
+  bool comma = false;
+  for (u32 p = 0; p < 6; p++) for (u32 c = 0; c < NCLS_ALL; c++) {
+    NativeAllocClass* a = &nap_classes[p][c];
+    u64 tagged = 0;
+    for (u32 t = 0; t < NAP_TAG_COUNT; t++)
+      nap_add(&tagged, nap_tags[p][t][c].requests);
+    if (tagged > a->requests || a->requests != a->fast + a->misses
+      || a->misses != a->cold + a->bank + a->fresh) valid = false;
+    if (!(a->requests || a->frees || a->fresh_words)) continue;
