+      "\"localFreelistHits\":%llu,\"misses\":%llu,\"coldRefills\":%llu,"
+      "\"bankRefills\":%llu,\"freshPageRefills\":%llu,"
+      "\"freshPageCapacityWords\":%llu,\"frees\":%llu}",
+      comma ? "," : "", p, c, (unsigned long long)(1ull << c),
+      (unsigned long long)a->requests, (unsigned long long)tagged,
+      (unsigned long long)(a->requests - tagged),
+      (unsigned long long)a->fast, (unsigned long long)a->misses,
+      (unsigned long long)a->cold, (unsigned long long)a->bank,
