+      fprintf(stderr, "%s{\"phase\":%u,\"tag\":%u,\"class\":%u,"
+        "\"requests\":%llu,\"payloadWords\":%llu,\"spareReuses\":%llu}",
+        comma ? "," : "", p, t, c, (unsigned long long)a->requests,
+        (unsigned long long)a->payload_words, (unsigned long long)a->spares);
+      comma = true;
