+  fprintf(stderr, "],\"valid\":%s,\"overflow\":%s,\"computeThreads\":%u,"
+    "\"counterBytes\":%llu,\"tagNames\":[", valid && !nap_overflow ? "true" : "false",
+    nap_overflow ? "true" : "false", pool_size,
+    (unsigned long long)(sizeof(nap_classes) + sizeof(nap_tags)));
+  for (u32 t = 0; t < NAP_TAG_COUNT; t++)
+    fprintf(stderr, "%s%s", t ? "," : "", NAP_TAG_NAMES[t]);
