 // Trusted orchestration only: runtime file IO, import resolution and the same
 // opaque chunk machine as checker_core_step_runtime.mjs. No parser,
 // elaborator, checker, emitter, source literal or expected result lives here.
-// Included unchanged by compile_book's ordinary foreign-effect mechanism.
+// PRIVATE diagnostic copy: entry markers originate in the C source generator.

 #include <sys/resource.h>
+
+// Entry-delimited logical intervals, NOT exclusive function or inclusive stack
+// attribution. Native dispatch/refcount/closure work between marks stays in its
+// current interval. No source semantics, request protocol or acceptance changes.
+typedef struct {
+  bool enabled, started, active, complete, reported, failed;
+  const char* failure;
+  int clock_errno;
+  u32 phase;
+  u64 wall_start, cpu_start, wall_last, cpu_last, wall_end, cpu_end;
+  u64 cpu_after_start, cpu_before_finish;
+  u64 wall_resolution, cpu_resolution, wall_reads, cpu_reads;
+  u64 wall[5], cpu[5], transitions[5][5];
+  u64 sites[NCP_SITE_COUNT], outside[NCP_SITE_COUNT];
+  u64 timed_sites[NCP_SITE_COUNT], same_phase_hits;
+  u64 marker_wall_bracket, marker_cpu_bracket, timed_marks;
+  double rusage_cpu_ms;
+} NativeCheckProfile;
+
+static NativeCheckProfile native_check_profile;
+static const char* NCP_PHASE_NAMES[] = {
+  "other", "body-inference", "termination", "affine-usage",
+  "publish-and-type-finishing"
+};
+
+static void native_check_profile_fail(const char* message) {
+  NativeCheckProfile* p = &native_check_profile;
+  if (!p->failed) {
+    p->failure = message;
+    p->clock_errno = errno;
+  }
+  p->failed = true;
+}
+
+static bool native_check_profile_clock(clockid_t clock, u64* result) {
+  struct timespec ts;
+  if (clock == CLOCK_MONOTONIC) native_check_profile.wall_reads++;
+  else native_check_profile.cpu_reads++;
+  if (clock_gettime(clock, &ts) != 0) {
+    native_check_profile_fail("clock_gettime");
+    return false;
+  }
+  *result = (u64)ts.tv_sec * 1000000000ull + (u64)ts.tv_nsec;
+  return true;
+}
+
+static void native_check_profile_add(u64 wall, u64 cpu) {
+  NativeCheckProfile* p = &native_check_profile;
+  if (wall < p->wall_last || cpu < p->cpu_last) {
+    errno = 0;
+    native_check_profile_fail("nonmonotonic profile clock");
+    return;
+  }
+  p->wall[p->phase] += wall - p->wall_last;
+  p->cpu[p->phase] += cpu - p->cpu_last;
+  p->wall_last = wall;
+  p->cpu_last = cpu;
+}
+
+static void native_check_profile_mark(u32 site) {
+  NativeCheckProfile* p = &native_check_profile;
+  if (!p->enabled) return;
+  if (site >= NCP_SITE_COUNT) {
+    errno = 0;
+    native_check_profile_fail("invalid generated profile site");
+    return;
+  }
+  if (!p->active) {
+    p->outside[site]++;
+    return;
+  }
+  p->sites[site]++;
+  u32 phase = NCP_ENTRY_PHASE[NCP_SITE_ENTRY[site]];
+  if (phase == p->phase) {
+    // Count repeated Other/reset entries without unnecessary clock reads.
+    p->same_phase_hits++;
+    return;
+  }
+  if (p->failed) return;
+  u64 wall, cpu, wall_after, cpu_after;
+  if (!native_check_profile_clock(CLOCK_MONOTONIC, &wall)
+      || !native_check_profile_clock(CLOCK_PROCESS_CPUTIME_ID, &cpu)) return;
+  native_check_profile_add(wall, cpu);
+  p->transitions[p->phase][phase]++;
+  p->phase = phase;
+  nap_phase = phase;
+  p->timed_sites[site]++;
+  p->timed_marks++;
+  // This interior bracket is a measured LOWER BOUND, not total instrumentation
+  // overhead: first clock reads, same-phase marks, ABI spill/codegen effects and
+  // the bracket's final reads are not all covered. Nothing is subtracted.
+  if (!native_check_profile_clock(CLOCK_PROCESS_CPUTIME_ID, &cpu_after)
+      || !native_check_profile_clock(CLOCK_MONOTONIC, &wall_after)) return;
+  if (wall_after < wall || cpu_after < cpu) {
+    errno = 0;
+    native_check_profile_fail("nonmonotonic marker bracket");
+    return;
+  }
+  p->marker_wall_bracket += wall_after - wall;
+  p->marker_cpu_bracket += cpu_after - cpu;
+}
+
+static void native_check_profile_report(void) {
+  NativeCheckProfile* p = &native_check_profile;
+  if (!p->enabled || p->reported) return;
+  p->reported = true;
+  u64 wall_sum = 0, cpu_sum = 0;
+  for (u32 i = 0; i < 5; i++) {
+    wall_sum += p->wall[i];
+    cpu_sum += p->cpu[i];
+  }
+  fprintf(stderr, "NATIVE_CHECK_INTERVALS {\"version\":1,\"complete\":%s,"
+    "\"started\":%s,\"activeAtExit\":%s,\"failed\":%s,\"clockErrno\":%d,"
+    "\"failure\":", p->complete ? "true" : "false",
+    p->started ? "true" : "false", p->active ? "true" : "false",
+    p->failed ? "true" : "false", p->clock_errno);
+  if (p->failure) fprintf(stderr, "\"%s\"", p->failure);
+  else fputs("null", stderr);
+  fprintf(stderr, ",\"computeThreads\":%u,\"wallStartNs\":\"%llu\","
+    "\"wallEndNs\":\"%llu\",\"cpuStartNs\":\"%llu\",\"cpuEndNs\":\"%llu\","
+    "\"wallSumNs\":%llu,\"cpuSumNs\":%llu,\"rusageCpuMs\":%.6f,"
+    "\"cpuStartBoundaryBracketNs\":%llu,\"cpuEndBoundaryBracketNs\":%llu,"
+    "\"wallClockResolutionNs\":%llu,\"cpuClockResolutionNs\":%llu,"
+    "\"monotonicReads\":%llu,\"processCpuReads\":%llu,"
+    "\"timedMarks\":%llu,\"samePhaseMarksWithoutClocks\":%llu,"
+    "\"markerInteriorWallBracketNs\":%llu,\"markerInteriorCpuBracketNs\":%llu,"
+    "\"bracketIsTotalOverhead\":false,\"intervalsIncludeInstrumentation\":true,"
+    "\"buckets\":[", pool_size,
+    (unsigned long long)p->wall_start, (unsigned long long)p->wall_end,
+    (unsigned long long)p->cpu_start, (unsigned long long)p->cpu_end,
+    (unsigned long long)wall_sum, (unsigned long long)cpu_sum, p->rusage_cpu_ms,
+    (unsigned long long)(p->cpu_after_start >= p->cpu_start
+      ? p->cpu_after_start - p->cpu_start : 0),
+    (unsigned long long)(p->cpu_end >= p->cpu_before_finish
+      ? p->cpu_end - p->cpu_before_finish : 0),
+    (unsigned long long)p->wall_resolution, (unsigned long long)p->cpu_resolution,
+    (unsigned long long)p->wall_reads, (unsigned long long)p->cpu_reads,
+    (unsigned long long)p->timed_marks, (unsigned long long)p->same_phase_hits,
+    (unsigned long long)p->marker_wall_bracket,
+    (unsigned long long)p->marker_cpu_bracket);
+  for (u32 i = 0; i < 5; i++) {
+    fprintf(stderr, "%s{\"phase\":\"%s\",\"wallNs\":%llu,\"cpuNs\":%llu}",
+      i ? "," : "", NCP_PHASE_NAMES[i],
+      (unsigned long long)p->wall[i], (unsigned long long)p->cpu[i]);
+  }
+  fputs("],\"transitions\":[", stderr);
+  for (u32 i = 0; i < 5; i++) for (u32 j = 0; j < 5; j++) {
+    fprintf(stderr, "%s%llu", i || j ? "," : "",
+      (unsigned long long)p->transitions[i][j]);
+  }
+  fputs("],\"entries\":[", stderr);
+  for (u32 entry = 0; entry < NCP_ENTRY_COUNT; entry++) {
+    u64 hits = 0, timed = 0, outside = 0;
+    for (u32 site = 0; site < NCP_SITE_COUNT; site++) {
+      if (NCP_SITE_ENTRY[site] != entry) continue;
+      hits += p->sites[site];
+      timed += p->timed_sites[site];
+      outside += p->outside[site];
+    }
+    fprintf(stderr, "%s{\"entry\":%u,\"source\":\"%s\",\"phase\":\"%s\","
+      "\"standaloneDispatchSlot\":%d,\"hits\":%llu,\"timedHits\":%llu,"
+      "\"outsideCheckHits\":%llu}", entry ? "," : "", entry,
+      NCP_ENTRY_NAMES[entry], NCP_PHASE_NAMES[NCP_ENTRY_PHASE[entry]],
+      NCP_ENTRY_SLOT[entry], (unsigned long long)hits,
+      (unsigned long long)timed, (unsigned long long)outside);
+  }
+  fputs("],\"sites\":[", stderr);
+  for (u32 site = 0; site < NCP_SITE_COUNT; site++) {
+    fprintf(stderr, "%s{\"site\":%u,\"entry\":%u,\"route\":%u,"
+      "\"emissionOwner\":\"%s\",\"nativeLabel\":\"%s\",\"dispatchSlot\":%d,"
+      "\"ownerLive\":%s,\"hits\":%llu,\"timedHits\":%llu,"
+      "\"outsideCheckHits\":%llu}", site ? "," : "", site,
+      NCP_SITE_ENTRY[site], NCP_SITE_ROUTE[site], NCP_SITE_OWNER[site],
+      NCP_SITE_LABEL[site], NCP_SITE_SLOT[site],
+      NCP_SITE_LIVE[site] ? "true" : "false",
+      (unsigned long long)p->sites[site],
+      (unsigned long long)p->timed_sites[site],
+      (unsigned long long)p->outside[site]);
+  }
+  fputs("]}\n", stderr);
+}
+
+static void native_check_profile_init(void) {
+  const char* flag = getenv("BEND_NATIVE_CHECK_INTERVALS");
+  if (!flag || strcmp(flag, "1") != 0) return;
+  NativeCheckProfile* p = &native_check_profile;
+  p->enabled = true;
+  if (atexit(native_check_profile_report) != 0) {
+    errno = 0;
+    native_check_profile_fail("atexit registration");
